<?php
require __DIR__.'/includes/app.php';require_admin();require __DIR__.'/includes/admin_tables.php';
$view=field($_GET,'view');if(!in_array($view,['dashboard','items','approvals','claims'],true))$view='dashboard';$adminSection=$view;
$tab=field($_GET,'tab');if(!in_array($tab,['all','active','claimed','rejected','archived','pending'],true))$tab='all';
$cs=field($_GET,'claim_status');if(!in_array($cs,['pending','resolved','rejected'],true))$cs='pending';
$counts=db()->query("SELECT SUM(moderation_status='pending') AS pending,SUM(moderation_status='approved' AND status<>'claimed') AS active,SUM(status='claimed') AS claimed FROM items")->fetch();$counts['pending_claims']=(int)db()->query("SELECT COUNT(*) FROM recovery_requests WHERE status='pending'")->fetchColumn();
$where=$view==='approvals' || $view==='dashboard' ? "moderation_status='pending'" : ['all'=>'1=1','active'=>"moderation_status='approved' AND status<>'claimed'",'claimed'=>"status='claimed'",'pending'=>"moderation_status='pending'",'rejected'=>"moderation_status='rejected'",'archived'=>"moderation_status='archived'"][$tab];
$q=mb_substr(field($_GET,'q'),0,100);$params=[];
if($q!==''){$where.=' AND (title LIKE ? OR location LIKE ?)';$params=['%'.$q.'%','%'.$q.'%'];}
$s=db()->prepare('SELECT COUNT(*) FROM items WHERE '.$where);$s->execute($params);$total=(int)$s->fetchColumn();$limit=$view==='dashboard' ? 5 : 15;$pages=max(1,(int)ceil($total/$limit));$page=min($pages,max(1,(int)field($_GET,'page')));
$s=db()->prepare('SELECT * FROM items WHERE '.$where.' ORDER BY id DESC LIMIT '.$limit.' OFFSET '.(($page-1)*$limit));$s->execute($params);$items=$s->fetchAll();
$s=db()->prepare('SELECT COUNT(*) FROM recovery_requests WHERE status=?');$s->execute([$cs]);$claimTotal=(int)$s->fetchColumn();$claimPages=max(1,(int)ceil($claimTotal/$limit));$cp=min($claimPages,max(1,(int)field($_GET,'claims')));
$s=db()->prepare('SELECT r.*,i.title FROM recovery_requests r JOIN items i ON i.id=r.item_id WHERE r.status=? ORDER BY r.id DESC LIMIT '.$limit.' OFFSET '.(($cp-1)*$limit));$s->execute([$cs]);$claims=$s->fetchAll();
$heading=['dashboard'=>'Dashboard','items'=>'Manage items','approvals'=>'Pending approvals','claims'=>'Claims'][$view];$title=$heading.' — ZPPSU';$adminLayout=true;require __DIR__.'/includes/header.php';require __DIR__.'/includes/admin_layout.php';
?>
<div class="workspace-heading"><div><span class="workspace-eyebrow">CAMPUS ADMINISTRATION</span><h2><?= e($heading) ?></h2><p><?= e(['dashboard'=>'Your campus noticeboard at a glance.','items'=>'Keep campus reports organized.','approvals'=>'Review reports before they appear on the noticeboard.','claims'=>'Verify ownership and coordinate safe returns.'][$view]) ?></p></div><a class="btn secondary" href="index.php">View noticeboard <span aria-hidden="true">&#8599;</span></a></div>
<?php if(isset($_SESSION['notice'])): ?><p class="notice" role="status"><?= e($_SESSION['notice']) ?></p><?php unset($_SESSION['notice']);endif ?>
<div class="admin-kpis"><?php foreach([['active','Total active items','&#9633;','items&tab=active'],['pending','Pending approvals','&#9719;','approvals'],['pending_claims','Pending claims','&#10003;','claims'],['claimed','Resolved / claimed','&#10004;','items&tab=claimed']] as [$key,$label,$icon,$target]): ?><a href="admin.php?view=<?= e($target) ?>"><div><span><?= e($label) ?></span><strong data-count="<?= e($key) ?>"><?= (int)$counts[$key] ?></strong></div><span class="kpi-icon" aria-hidden="true"><?= $icon ?></span></a><?php endforeach ?></div>
<?php if($view!=='claims'): ?><section class="workspace-card"><div class="workspace-card-heading"><div><h3><?= $view==='dashboard' ? 'Reports awaiting review' : ($view==='approvals' ? 'Approval queue' : 'Campus items') ?></h3><span><?= $total ?> <?= $total===1 ? 'report' : 'reports' ?></span></div><?php if($view==='dashboard'): ?><a class="subtle-link" href="admin.php?view=approvals">View all &#8594;</a><?php endif ?></div>
<?php if($view==='items'): ?><div class="workspace-toolbar"><div class="admin-filters"><?php foreach(['all','active','pending','claimed','rejected','archived'] as $state): ?><a class="<?= $state===$tab ? 'selected' : '' ?>" href="?<?= e(http_build_query(['view'=>'items','tab'=>$state,'q'=>$q])) ?>"><?= ucfirst($state) ?></a><?php endforeach ?></div><form method="get" class="admin-search"><input type="hidden" name="view" value="items"><input type="hidden" name="tab" value="<?= e($tab) ?>"><label class="sr-only" for="item-search">Search items</label><input id="item-search" name="q" maxlength="100" value="<?= e($q) ?>" placeholder="Search item or location"><button aria-label="Search items">&#8594;</button></form></div><?php endif ?>
<?php item_table($items,$view==='items' ? 'No matching items.' : 'All caught up. No pending reports.'); ?>
<?php if($pages>1 && $view!=='dashboard'): ?><div class="admin-pagination"><?php if($page>1): ?><a href="?<?= e(http_build_query(['view'=>$view,'tab'=>$tab,'q'=>$q,'page'=>$page-1])) ?>">Previous</a><?php endif ?><span>Page <?= $page ?> of <?= $pages ?></span><?php if($page<$pages): ?><a href="?<?= e(http_build_query(['view'=>$view,'tab'=>$tab,'q'=>$q,'page'=>$page+1])) ?>">Next</a><?php endif ?></div><?php endif ?></section><?php endif ?>
<?php if(in_array($view,['dashboard','claims'],true)): ?><section class="workspace-card"><div class="workspace-card-heading"><div><h3><?= $view==='dashboard' ? 'Claims awaiting verification' : 'Recovery requests' ?></h3><span><?= $claimTotal ?> requests</span></div><?php if($view==='dashboard'): ?><a class="subtle-link" href="admin.php?view=claims">View all &#8594;</a><?php endif ?></div><?php if($view==='claims'): ?><div class="workspace-toolbar"><div class="admin-filters"><?php foreach(['pending'=>'Incoming','resolved'=>'Approved','rejected'=>'Rejected'] as $value=>$label): ?><a class="<?= $value===$cs ? 'selected' : '' ?>" href="?view=claims&amp;claim_status=<?= $value ?>"><?= $label ?></a><?php endforeach ?></div></div><?php endif ?><?php claim_table($claims); ?>
<?php if($claimPages>1 && $view==='claims'): ?><div class="admin-pagination"><?php if($cp>1): ?><a href="?view=claims&amp;claim_status=<?= $cs ?>&amp;claims=<?= $cp-1 ?>">Previous</a><?php endif ?><span>Page <?= $cp ?> of <?= $claimPages ?></span><?php if($cp<$claimPages): ?><a href="?view=claims&amp;claim_status=<?= $cs ?>&amp;claims=<?= $cp+1 ?>">Next</a><?php endif ?></div><?php endif ?></section><?php endif ?>
<?php require __DIR__.'/includes/admin_footer.php'; ?>
